-- Generated by: migrate -sql. Run against an empty database, e.g.
--   createdb gateway_dev && psql -v ON_ERROR_STOP=1 -1 -d gateway_dev -f schema.sql
CREATE TABLE IF NOT EXISTS schema_migrations (
  version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());

-- ==== 0001_roles.sql ====
-- Application roles. They are NOLOGIN here; an operator gives them a password
-- (or maps a login role into them) outside of migrations so no secret lives in SQL.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gateway_app') THEN
    CREATE ROLE gateway_app NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gateway_ops') THEN
    CREATE ROLE gateway_ops NOLOGIN;
  END IF;
END $$;
INSERT INTO schema_migrations (version) VALUES ('0001_roles');

-- ==== 0002_api_clients.sql ====
-- Gateway API clients. Only a hash of the key is stored. A key looks like
-- gw_<key_id>_<secret>; key_id is public and used for lookup.
CREATE TABLE api_clients (
  id          bigserial   PRIMARY KEY,
  name        text        NOT NULL UNIQUE CHECK (length(name) BETWEEN 1 AND 100),
  role        text        NOT NULL DEFAULT 'caller' CHECK (role IN ('caller', 'admin')),
  key_id      text        NOT NULL UNIQUE,
  key_hash    bytea       NOT NULL CHECK (length(key_hash) = 32),
  status      text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
INSERT INTO schema_migrations (version) VALUES ('0002_api_clients');

-- ==== 0003_provider_configs.sql ====
-- Provider configuration, kept separate from payment transactions.
CREATE TABLE provider_configs (
  id                        bigserial   PRIMARY KEY,
  name                      text        NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  provider                  text        NOT NULL CHECK (provider IN ('paypal', 'xendit', 'fake')),
  environment               text        NOT NULL CHECK (environment IN ('sandbox', 'production')),
  status                    text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  allowed_currencies        text[]      NOT NULL CHECK (cardinality(allowed_currencies) > 0),
  settings                  jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(settings) = 'object'),
  active_credential_version integer,
  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, environment, name)
);

-- Which caller may use which configuration.
CREATE TABLE client_config_access (
  client_id          bigint      NOT NULL REFERENCES api_clients (id) ON DELETE CASCADE,
  provider_config_id bigint      NOT NULL REFERENCES provider_configs (id) ON DELETE CASCADE,
  granted_at         timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (client_id, provider_config_id)
);
INSERT INTO schema_migrations (version) VALUES ('0003_provider_configs');

-- ==== 0004_provider_credentials.sql ====
-- Encrypted provider credentials, one row per version. Plaintext never reaches
-- the database; the master key never lives here.
CREATE TABLE provider_credentials (
  provider_config_id bigint      NOT NULL REFERENCES provider_configs (id) ON DELETE CASCADE,
  version            integer     NOT NULL CHECK (version > 0),
  ciphertext         bytea       NOT NULL,
  webhook_ciphertext bytea,
  key_id             text        NOT NULL,
  status             text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retired')),
  created_by         text        NOT NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  retired_at         timestamptz,
  PRIMARY KEY (provider_config_id, version)
);

-- Exactly one active version per config.
CREATE UNIQUE INDEX provider_credentials_one_active
  ON provider_credentials (provider_config_id) WHERE status = 'active';

-- The pointer on provider_configs must reference an existing version. Deferred so
-- a config and its first credentials can be inserted in one transaction.
ALTER TABLE provider_configs
  ADD CONSTRAINT provider_configs_active_credential_fk
  FOREIGN KEY (id, active_credential_version)
  REFERENCES provider_credentials (provider_config_id, version)
  DEFERRABLE INITIALLY DEFERRED;
INSERT INTO schema_migrations (version) VALUES ('0004_provider_credentials');

-- ==== 0005_payment_transactions.sql ====
CREATE TABLE payment_transactions (
  id                  uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
  client_id           bigint        NOT NULL REFERENCES api_clients (id) ON DELETE RESTRICT,
  provider_config_id  bigint        NOT NULL REFERENCES provider_configs (id) ON DELETE RESTRICT,
  uniquecode          text          NOT NULL CHECK (uniquecode ~ '^[A-Za-z0-9._:-]{1,64}$'),
  amount              numeric(20,4) NOT NULL CHECK (amount > 0),
  currency            char(3)       NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  status              text          NOT NULL CHECK (status IN
                        ('creating', 'pending', 'paid', 'failed', 'expired', 'cancelled', 'refunded')),
  provider_status     text,
  provider_ref        text,
  payment_url         text,
  expires_at          timestamptz,
  paid_at             timestamptz,
  failure_code        text,
  request_fingerprint bytea         NOT NULL CHECK (length(request_fingerprint) = 32),
  credential_version  integer,
  current_fence       bigint        NOT NULL DEFAULT 0,
  created_at          timestamptz   NOT NULL DEFAULT now(),
  updated_at          timestamptz   NOT NULL DEFAULT now(),
  -- uniquecode is unique per caller (decision D1).
  UNIQUE (client_id, uniquecode),
  CHECK (paid_at IS NULL OR status IN ('paid', 'refunded'))
);

-- One provider payment maps to at most one transaction.
CREATE UNIQUE INDEX payment_transactions_provider_ref
  ON payment_transactions (provider_config_id, provider_ref) WHERE provider_ref IS NOT NULL;
CREATE INDEX payment_transactions_expiry ON payment_transactions (expires_at) WHERE status = 'pending';
CREATE INDEX payment_transactions_creating ON payment_transactions (updated_at) WHERE status = 'creating';
INSERT INTO schema_migrations (version) VALUES ('0005_payment_transactions');

-- ==== 0006_payment_attempts.sql ====
-- One row per provider call. fence_token equals payment_transactions.current_fence
-- at the time the attempt started; a result is accepted only while it still matches.
CREATE TABLE payment_attempts (
  id                       bigserial   PRIMARY KEY,
  transaction_id           uuid        NOT NULL REFERENCES payment_transactions (id) ON DELETE CASCADE,
  attempt_no               integer     NOT NULL CHECK (attempt_no > 0),
  fence_token              bigint      NOT NULL,
  lease_owner              text        NOT NULL,
  lease_expires_at         timestamptz NOT NULL,
  state                    text        NOT NULL DEFAULT 'in_flight'
                             CHECK (state IN ('in_flight', 'succeeded', 'failed', 'unknown')),
  provider_idempotency_key text        NOT NULL,
  error_code               text,
  created_at               timestamptz NOT NULL DEFAULT now(),
  finished_at              timestamptz,
  UNIQUE (transaction_id, attempt_no),
  UNIQUE (transaction_id, fence_token)
);
CREATE INDEX payment_attempts_open ON payment_attempts (lease_expires_at) WHERE state = 'in_flight';
INSERT INTO schema_migrations (version) VALUES ('0006_payment_attempts');

-- ==== 0007_status_history.sql ====
-- Append-only record of every status change (immutability enforced in 0011).
CREATE TABLE payment_status_history (
  id               bigserial   PRIMARY KEY,
  transaction_id   uuid        NOT NULL REFERENCES payment_transactions (id) ON DELETE CASCADE,
  from_status      text,
  to_status        text        NOT NULL,
  reason           text        NOT NULL,
  actor_type       text        NOT NULL CHECK (actor_type IN ('client', 'admin', 'system', 'webhook', 'operator')),
  actor_id         text        NOT NULL,
  webhook_event_id bigint,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payment_status_history_tx ON payment_status_history (transaction_id, id);
INSERT INTO schema_migrations (version) VALUES ('0007_status_history');

-- ==== 0008_webhook_events.sql ====
-- Every webhook delivery, verified or not. Real adapters arrive in Phase 4;
-- the table exists now so the settlement path is final.
CREATE TABLE webhook_events (
  id                 bigserial   PRIMARY KEY,
  provider           text        NOT NULL,
  event_id           text,
  provider_config_id bigint      REFERENCES provider_configs (id),
  transaction_id     uuid        REFERENCES payment_transactions (id),
  verified           boolean     NOT NULL DEFAULT false,
  outcome            text,
  payload            jsonb,
  received_at        timestamptz NOT NULL DEFAULT now(),
  processed_at       timestamptz,
  CHECK (NOT verified OR event_id IS NOT NULL)
);
-- Duplicate guard. Only verified events count, so an unverified sender cannot
-- poison the key of a real event.
CREATE UNIQUE INDEX webhook_events_dedup ON webhook_events (provider, event_id) WHERE verified;

ALTER TABLE payment_status_history
  ADD CONSTRAINT payment_status_history_event_fk
  FOREIGN KEY (webhook_event_id) REFERENCES webhook_events (id);
INSERT INTO schema_migrations (version) VALUES ('0008_webhook_events');

-- ==== 0009_review_items.sql ====
-- Items a human must look at (money may have moved in a way we did not record).
CREATE TABLE review_items (
  id             bigserial   PRIMARY KEY,
  transaction_id uuid        NOT NULL REFERENCES payment_transactions (id) ON DELETE CASCADE,
  kind           text        NOT NULL CHECK (kind IN
                   ('paid_after_expiry', 'stale_result', 'unknown_outcome_exhausted', 'amount_mismatch')),
  state          text        NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'resolved')),
  details        jsonb       NOT NULL DEFAULT '{}'::jsonb,
  created_at     timestamptz NOT NULL DEFAULT now(),
  resolved_by    text,
  resolution     text,
  resolved_at    timestamptz,
  CHECK ((state = 'open') = (resolved_at IS NULL))
);
-- One open item of a kind per transaction.
CREATE UNIQUE INDEX review_items_open_unique ON review_items (transaction_id, kind) WHERE state = 'open';
INSERT INTO schema_migrations (version) VALUES ('0009_review_items');

-- ==== 0010_audit_log.sql ====
-- Append-only record of administrative actions. Never contains secrets.
CREATE TABLE audit_log (
  id         bigserial   PRIMARY KEY,
  actor_type text        NOT NULL CHECK (actor_type IN ('admin', 'operator', 'system')),
  actor_id   text        NOT NULL CHECK (actor_id <> ''),
  action     text        NOT NULL,
  target     text,
  details    jsonb       NOT NULL DEFAULT '{}'::jsonb,
  at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_at ON audit_log (at);
INSERT INTO schema_migrations (version) VALUES ('0010_audit_log');

-- ==== 0011_triggers_grants.sql ====
-- Append-only enforcement: history and audit rows can never change or vanish.
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
END $$;

CREATE TRIGGER payment_status_history_immutable BEFORE UPDATE OR DELETE ON payment_status_history
  FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER payment_status_history_no_truncate BEFORE TRUNCATE ON payment_status_history
  FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER audit_log_immutable BEFORE UPDATE OR DELETE ON audit_log
  FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION reject_mutation();

-- Privileges. gateway_app is the running server (including the admin API);
-- gateway_ops is the CLI. Neither can run DDL.
-- Schema-level grants follow the schema the migration runs in (public in normal
-- use; a throwaway schema in integration tests).
DO $$
BEGIN
  EXECUTE format('GRANT USAGE ON SCHEMA %I TO gateway_app, gateway_ops', current_schema());
  EXECUTE format('GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA %I TO gateway_app, gateway_ops', current_schema());
END $$;

GRANT SELECT ON api_clients TO gateway_app;
GRANT SELECT, INSERT, UPDATE ON api_clients TO gateway_ops;

GRANT SELECT, INSERT, UPDATE ON provider_configs, provider_credentials TO gateway_app, gateway_ops;
GRANT SELECT, INSERT, DELETE ON client_config_access TO gateway_app, gateway_ops;
GRANT SELECT, INSERT, UPDATE ON payment_transactions, payment_attempts, webhook_events, review_items
  TO gateway_app, gateway_ops;
GRANT SELECT, INSERT ON payment_status_history, audit_log TO gateway_app, gateway_ops;
INSERT INTO schema_migrations (version) VALUES ('0011_triggers_grants');

-- ==== 0012_provider_stripe.sql ====
-- Allow the Stripe provider. The CHECK on provider_configs.provider was created
-- inline in 0003, so it carries PostgreSQL's generated name.
ALTER TABLE provider_configs DROP CONSTRAINT provider_configs_provider_check;
ALTER TABLE provider_configs
  ADD CONSTRAINT provider_configs_provider_check
  CHECK (provider IN ('paypal', 'xendit', 'stripe', 'fake'));
INSERT INTO schema_migrations (version) VALUES ('0012_provider_stripe');

-- ==== 0013_provider_midtrans.sql ====
-- Allow the Midtrans provider.
ALTER TABLE provider_configs DROP CONSTRAINT provider_configs_provider_check;
ALTER TABLE provider_configs
  ADD CONSTRAINT provider_configs_provider_check
  CHECK (provider IN ('paypal', 'xendit', 'stripe', 'midtrans', 'fake'));
INSERT INTO schema_migrations (version) VALUES ('0013_provider_midtrans');
